export function createSearch(fetchResults, onChange) {
  let generation = 0;
  return { async search(query) {
    const request = ++generation;
    onChange({ query, status: 'pending', results: [], error: null });
    let state;
    try {
      const results = await fetchResults(query);
      state = { query, status: 'success', results, error: null };
    } catch {
      state = { query, status: 'error', results: [], error: 'Search failed' };
    }
    if (request === generation) onChange(state);
  } };
}

