export function createSearch(fetchResults, onChange) {
  let latestQuery;
  return { async search(query) {
    latestQuery = query;
    onChange({ query, status: 'pending', results: [], error: null });
    let state;
    try {
      const results = await fetchResults(query);
      state = { query, status: 'success', results, error: null };
    } catch {
      state = { query, status: 'error', results: [], error: 'Search failed' };
    }
    if (query === latestQuery) onChange(state);
  } };
}

grid-paste.reference:
export function planPaste(text, height, width, originRow, originColumn) {
  const rejected = { ok: false, writes: [] };
  if (typeof text !== 'string' || ![height, width, originRow, originColumn].every(Number.isSafeInteger)
      || height < 1 || width < 1 || originRow < 0 || originColumn < 0
      || originRow >= height || originColumn >= width) return rejected;
  if (!text) return { ok: true, writes: [] };
  const normalized = text.replace(/\r\n/g, '\n');
  if (normalized.includes('\r')) return rejected;
  const records = normalized.endsWith('\n') ? normalized.slice(0, -1) : normalized;
  const writes = [];
  for (const [dy, line] of records.split('\n').entries()) {
    const fields = line.split('\t');
    if (dy >= height - originRow || fields.length > width - originColumn) return rejected;
    for (const [dx, value] of fields.entries()) writes.push({ row: originRow + dy, column: originColumn + dx, value });
  }
  return { ok: true, writes };
}

